/* ScopeWise uses text escaping and delegated events; no raw model HTML is rendered. */
const state = { user: null, status: {}, courses: [], bundle: null, page: 'overview', register: false, chat: [], sourceResults: null, sourceMode: null };
const root = document.querySelector('#app');
const modal = document.querySelector('#modal');
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names = {aligned:'In scope', partial:'Partly in scope', beyond_scope:'Explicitly excluded', uncertain:'Needs evidence', matches_guidance:'Matches guidance', different_format:'Different format', unknown:'Not established', required:'Required', excluded:'Excluded'};
const sourceRoleNames = {syllabus:'Current scope',notes:'Current notes',paper:'Past questions',guidance:'Current guidance'};
const pill = (key, text) => `<span class="pill ${escape(key)}">${escape(text || names[key] || key)}</span>`;
const button = (action, text, id = '', cls = '') => `<button class="${cls}" data-action="${action}" data-id="${escape(id)}">${text}</button>`;
const courseId = () => state.bundle?.course.id;
const latest = () => state.bundle?.analyses.at(-1);
function packAvailability() {
  const matches=latest()?.matches||[],questions=new Map((state.bundle?.questions||[]).map(q=>[q.id,q])),seen=new Set();
  let available=0,duplicates=0,notSuitable=0;
  for(const match of matches){const question=questions.get(match.question_id);if(!question)continue;if(!['aligned','partial'].includes(match.scope_status)){notSuitable++;continue;}const fingerprint=(question.text.toLowerCase().match(/\w+/g)||[]).join(' ');if(seen.has(fingerprint)){duplicates++;continue;}seen.add(fingerprint);available++;}
  return {available,duplicates,notSuitable};
}
let toastTimer, pollTimer;
function toast(text) { const box = document.querySelector('#toast'); box.textContent = text; box.hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => box.hidden = true, 7000); }
async function api(path, options = {}) {
  const headers = {...(options.body instanceof FormData ? {} : {'Content-Type':'application/json'}), ...(state.user?.csrf ? {'X-CSRF-Token':state.user.csrf} : {}), ...options.headers};
  const response = await fetch('/api' + path, {...options, headers, credentials:'same-origin'});
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 401 && state.user) { state.user = null; state.bundle = null; render(); }
    throw new Error(typeof data.detail === 'string' ? data.detail : response.status === 422 ? 'Check the fields and source quote, then try again.' : 'Request failed. Please try again.');
  }
  return data;
}
const post = (path, body = {}) => api(path, {method:'POST', body:JSON.stringify(body)});
const patch = (path, body) => api(path, {method:'PATCH', body:JSON.stringify(body)});
function showModal(title, content) {
  document.querySelector('#modal-content').innerHTML = `<div class="modal-header"><h2 id="modal-title">${escape(title)}</h2>${button('close','×','','text')}</div>${content}`;
  if (!modal.open) modal.showModal();
}
function formFooter(label = 'Save changes') { return `<div class="error" role="alert"></div><div class="modal-footer">${button('close','Cancel')}<button type="submit" class="primary">${label}</button></div>`; }
async function load(id = courseId()) {
  state.courses = await api('/courses');
  const selected = state.courses.find(c => c.id === id) || state.courses[0];
  state.bundle = selected ? await api(`/courses/${selected.id}`) : null;
  render(); schedulePoll();
}
function schedulePoll() {
  clearTimeout(pollTimer);
  if (!state.bundle?.jobs.some(j => ['queued','running'].includes(j.status))) return;
  pollTimer = setTimeout(async () => {
    try {
      const id = courseId(); const bundle = await api(`/courses/${id}`);
      if (courseId() !== id) return;
      const wasActive = state.bundle.jobs.filter(j => ['queued','running'].includes(j.status)).map(j => j.id);
      state.bundle = bundle;
      const finished = bundle.jobs.find(j => wasActive.includes(j.id) && ['completed','failed'].includes(j.status));
      if (finished) {
        if (finished.status === 'completed' && finished.action === 'prepare') state.page = 'review';
        if (finished.status === 'completed' && finished.action === 'generate_pack') state.page = 'packs';
        const completedMessage=finished.action==='prepare'?'Your review is ready. Check the AI-prepared judgments.':finished.action==='generate_pack'?'Your requested practice pack is ready.':'Analysis finished. Review the new suggestions.';
        toast(finished.status === 'completed' ? completedMessage : finished.error);
      }
      if (!modal.open && !document.querySelector('textarea:focus')) render();
      schedulePoll();
    } catch (error) { toast(error.message); }
  }, 4000);
}
function evidence(ev) {
  if (!ev) return '';
  const doc = state.bundle.documents.find(d => d.id === ev.document_id);
  return `<blockquote class="evidence">“${escape(ev.quote)}”<br><button class="text" data-action="source" data-id="${escape(ev.document_id)}" data-page="${ev.page}">${escape(doc?.name || 'Source')} · page ${ev.page} ↗</button></blockquote>`;
}
function heading(eyebrow, title, description, actions = '') { return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${description}</p></div><div class="actions">${actions}</div></div>`; }
function authView() {
  return `<div class="auth-layout"><section class="auth-story"><div class="brand"><span class="mark">↗</span> ScopeWise</div><span class="eyebrow">Less guesswork. Better practice.</span><h1>Old papers.<br>Current perspective.</h1><p>Find the questions that fit the module you’re studying today. See the evidence, spot the gaps, and make your practice count.</p><div class="auth-example"><div class="eyebrow">Same topic. Two different judgments.</div><h3 class="auth-example-title">“Define primary and candidate keys.”</h3><div class="actions">${pill('aligned')}${pill('different_format')}</div><p class="small-copy muted">Still part of the syllabus. But current guidance asks you to apply the concept to a worked example.</p></div><span class="auth-badge">SDG 4 · Quality education</span></section><main id="main" class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Your private workspace</div><h2>${state.register ? 'Start with your module' : 'Welcome back'}</h2><p class="muted">${state.register ? 'Create an account for this invite-only pilot.' : 'Sign in to pick up your practice.'}</p><form data-form="auth"><label for="username">Username</label><input id="username" name="username" autocomplete="username" pattern="[a-zA-Z0-9_.\\-]{3,40}" minlength="3" maxlength="40" required><label for="password">Password${state.register ? ' · at least 12 characters' : ''}</label><input id="password" name="password" type="password" autocomplete="${state.register ? 'new-password' : 'current-password'}" minlength="${state.register ? 12 : 1}" maxlength="128" required>${state.register ? `<label for="invitation">Invitation code</label><input id="invitation" name="invitation" value="${escape(state.status.development_invitation || '')}" required>` : ''}<div class="error" role="alert"></div><button class="primary" type="submit">${state.register ? 'Create workspace' : 'Sign in'} ↗</button></form><div class="auth-toggle"><span class="muted">${state.register ? 'Already have an account?' : 'First time here?'}</span> ${button('auth-toggle',state.register ? 'Sign in' : 'Create account','','text')}</div><p class="footer-note">${state.status.development ? 'Local development · ' : ''}Private pilot. Bring materials you have permission to use. No exam predictions, no generated answers.</p></div></main></div>`;
}
function render() {
  if (!state.user) { root.innerHTML = authView(); return; }
  const b = state.bundle, nav = [['overview','◷','Home'],['sources','1','Upload materials'],['review','2','Check results'],['packs','3','Practice pack']];
  const more=b?`<details class="side-more"><summary>More options</summary><div>${button('edit-course','Module settings','','nav-button')}${button('nav','Review extracted scope','scope','nav-button')}${button('nav','Ask ScopeWise','assistant','nav-button')}${button('new-course','New module','','nav-button')}${button('telegram','Connect Telegram','','nav-button')}</div></details>`:'';
  root.innerHTML = `<div class="layout"><aside class="sidebar"><div class="brand"><span class="mark">↗</span> ScopeWise</div><label class="side-label" for="course-switch">Your module</label><select id="course-switch" aria-label="Switch module">${state.courses.length ? state.courses.map(c => `<option value="${c.id}" ${c.id === courseId() ? 'selected' : ''}>${escape(c.title)}</option>`).join('') : '<option>No modules yet</option>'}</select><nav aria-label="Study workflow">${nav.map(([id,icon,label]) => `<button class="nav-button ${state.page === id ? 'active' : ''}" data-action="nav" data-id="${id}" ${state.page === id ? 'aria-current="page"' : ''}><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav>${more}<div class="sidebar-bottom"><p class="small-copy"><span class="local-dot"></span>Runs with local AI</p><p class="footer-note">Private local workspace</p></div></aside><div class="main-wrap"><header class="topbar"><span class="topbar-path">${escape(b?.course.title || 'Getting started')}</span><div class="actions"><span class="avatar">${escape(state.user.username.slice(0,2).toUpperCase())}</span><span class="small-copy">${escape(state.user.username)}</span>${button('logout','Sign out','','text')}</div></header><main id="main" class="content">${b ? jobNotice() + ({overview:overview, sources:sourcesView, scope:scopeView, review:reviewView, packs:packsView, assistant:assistantView}[state.page] || overview)() : welcome()}</main></div></div>`;
}
function welcome() { return heading('A focused start','Your module, in perspective.','Upload the material you already have. ScopeWise prepares the evidence review.') + `<div class="hero"><div><span class="eyebrow">Start with the material</span><h2>Upload once.<br>Review what matters.</h2><p>Choose a current syllabus or module outline and an old paper. Add current assessment guidance when available. ScopeWise creates the workspace, finds cited scope and questions, and prepares the comparison.</p><div class="actions hero-actions">${button('guided-upload','Start from my material ↗','','primary')}${button('sample','Explore sample module')}${button('new-course','Create an empty module')}</div></div><div class="hero-art" aria-hidden="true">◎</div></div><p class="footer-note">Every AI-prepared judgment requires human review before it can enter a practice pack. The sample is original demonstration material, not a live model result.</p>`; }
function jobNotice() {
  const jobs=state.bundle.jobs,active=jobs.find(j=>['running','queued'].includes(j.status));
  const failed=[...jobs].reverse().find(j=>j.status==='failed'&&!j.acknowledged);
  if(active){const message=active.action==='extract'?'Reading the source and finding draft items':active.action==='prepare'?'Preparing your scope, questions, and comparison':active.action==='generate_pack'?'Generating grounded practice questions and building your pack':'Comparing approved questions';return `<div class="job-bar" role="status">${pill(active.status)} ${message}… You can keep browsing while the local model works.</div>`;}
  if(!failed)return '';
  const alias=String(failed.error||'').includes('unknown source reference');
  const missing=String(failed.error||'').includes('Approve at least one objective and one question');
  const message=alias?'The local model used a citation that was not in your approved material. Nothing from that run was saved.':missing?'The first preparation did not produce usable cited items. Retry it from the uploaded files.':(failed.error||'The local model could not finish. Nothing from that run was saved.');
  const retry=['prepare','analyze'].includes(failed.action)?button('retry-review','Retry automatic preparation',failed.id,'primary'):'';
  return `<section class="recovery" role="alert"><div><strong>We could not finish that AI review</strong><p>${escape(message)}</p></div><div class="actions">${retry}${button('dismiss-job','Dismiss',failed.id,'text')}</div></section>`;
}
function changeImpact() {
  const impact=state.bundle?.change_impact;if(!impact)return '';
  const guidanceReview=!impact.has_current_guidance&&impact.events.some(event=>['lecturer_changed','guidance_changed'].includes(event.type));
  if(!impact.stale_analysis_count&&!impact.stale_pack_count&&!impact.retired_objective_count&&!guidanceReview)return '';
  const actions={sources:['Review current sources','sources'],scope:['Confirm current scope','scope'],review:['Run a fresh comparison','review'],packs:['Rebuild your practice pack','packs']};
  const [label,page]=actions[impact.next_action]||actions.review;
  const counts=[
    [impact.stale_analysis_count,'comparison'],
    [impact.stale_pack_count,'practice pack'],
    [impact.retired_objective_count,'retired objective']
  ].filter(([count])=>count).map(([count,name])=>`<span><strong>${count}</strong> ${name}${count===1?'':'s'} need attention</span>`).join('');
  const history=impact.events.length?`<details><summary>See what changed</summary><ol>${impact.events.map(event=>`<li><strong>${escape(event.summary)}</strong><span>Scope v${event.revision}</span></li>`).join('')}</ol></details>`:'';
  return `<section class="impact-card" aria-labelledby="impact-title"><div class="impact-main"><span class="eyebrow">Change impact</span><h2 id="impact-title">Your module changed</h2><p>${escape(impact.statement)}</p><div class="impact-counts">${counts||'<span>Current guidance needs confirmation</span>'}</div>${history}</div><div class="impact-action"><span class="small-copy">Recommended next step</span>${button('nav',label+' ↗',page,'primary')}</div></section>`;
}
function provenanceView(questionId) {
  const trace=latest()?.provenance?.[questionId];
  if(!trace)return '<p class="run-details-missing">Run details are unavailable for this earlier review.</p>';
  const retrieval=trace.retrieval_mode==='semantic'?'Meaning search':'Keyword fallback';
  const discarded=trace.discarded_references?`<li>Discarded ${trace.discarded_references} unsupported model reference${trace.discarded_references===1?'':'s'}</li>`:'';
  return `<section class="run-details" aria-label="How this comparison was made"><div><span class="run-mark" aria-hidden="true">AK</span><div><strong>Compared by the local ScopeWise agent</strong><p>${retrieval} · Checked ${trace.candidate_objective_count} possible objective${trace.candidate_objective_count===1?'':'s'} and ${trace.exclusions_checked} explicit exclusion${trace.exclusions_checked===1?'':'s'} · Used ${trace.guidance_chunks} current-guidance excerpt${trace.guidance_chunks===1?'':'s'}</p></div></div><strong class="human-check">You still make the final decision</strong>${discarded?`<ul>${discarded}</ul>`:''}<details><summary>Technical details for judges</summary><p>Agent Kernel <code>AgentService</code> ran the registered <code>${escape(trace.agent)}</code> agent. The server validated aliases and citations before saving this result.</p></details></section>`;
}
function overview() {
  const b = state.bundle, a = latest(), valid = a && !a.stale, matches = valid ? a.matches : [], required = b.objectives.filter(o => o.approved && o.kind === 'required');
  const covered = new Set(matches.filter(m => m.reviewed && m.scope_status === 'aligned').flatMap(m => m.objective_ids));
  const hasScope=b.documents.some(d=>d.approved&&['syllabus','notes'].includes(d.role)),hasPaper=b.documents.some(d=>d.approved&&d.role==='paper');
  const currentPack=[...b.packs].reverse().find(pack=>!pack.stale),availability=packAvailability();
  const next=!hasScope||!hasPaper?['sources','Upload your material']:!valid?['review','Prepare results']:!currentPack?['review','Make a practice pack']:['packs','Open latest pack'];
  const status=currentPack?`${currentPack.questions.length} questions ready in your latest pack`:valid?`${availability.available} unique uploaded questions are suitable before generation`:'Upload your files and ScopeWise will prepare the comparison';
  return heading('Home',escape(b.course.title),'Your next task stays visible; detailed controls remain available under More options.',button('nav',next[1]+' ↗',next[0],'primary')) + changeImpact() +
    `<section class="panel focus-panel"><span class="eyebrow">Current status</span><h2>${escape(status)}</h2><p>${currentPack?'Open the pack to study, download it, or create another difficulty level.':'ScopeWise uses uploaded questions first and can generate missing Easy, Medium or Difficult practice.'}</p></section>`+
    `<details class="advanced-section"><summary>View module details and coverage</summary><div class="stats compact-stats">${[['Materials',b.documents.length,'Private files'],['Source questions',b.questions.filter(q=>q.approved).length,'From uploaded papers'],['Objectives covered',`${required.filter(o=>covered.has(o.id)).length} / ${required.length}`,'Reviewed links']].map(([label,value,detail])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-detail">${detail}</div></div>`).join('')}</div><section class="panel nested-panel"><div class="panel-title"><h2>Coverage</h2>${pill('unknown','Not exam readiness')}</div>${required.length?required.map(o=>`<div class="coverage-item"><span class="coverage-icon ${covered.has(o.id)?'':'missing'}">${covered.has(o.id)?'✓':'○'}</span><div>${escape(o.text)}<div class="small-copy muted">${covered.has(o.id)?'Linked to reviewed practice':'No reviewed full match yet'}</div></div>`).join(''):'<p class="muted">Coverage appears after material is prepared.</p>'}</section></details>`;
}
function sourcesView() {
  const docs=state.bundle.documents;
  const search=state.sourceResults===null?'':`<div class="search-results" aria-live="polite">${state.sourceResults.length?`<p class="small-copy muted">${state.sourceMode==='semantic'?'Meaning-based':'Keyword'} matches · exact excerpts from your files</p>${state.sourceResults.map(r=>`<button class="search-result" data-action="source" data-id="${r.document_id}" data-page="${r.page}"><strong>${escape(r.document_name)} · ${r.document_name.toLowerCase().endsWith('.pptx')?'slide':'page'} ${r.page}</strong><span>${escape(r.text.slice(0,280))}${r.text.length>280?'…':''}</span></button>`).join('')}`:'<p class="notice neutral">No matching passage found. Try a specific concept or phrase from the module.</p>'}</div>`;
  const library=docs.length?`<div class="doc-grid">${docs.map(d=>{const ext=d.name.toLowerCase().endsWith('.pptx')?'PPTX':d.name.toLowerCase().endsWith('.pdf')?'PDF':'TEXT';const index=d.index_status==='semantic'?'Meaning search ready':'Keyword search ready';return `<article class="doc-card"><div class="actions"><span class="doc-icon">${ext}</span>${pill('unknown',sourceRoleNames[d.role]||d.role)}${pill(d.approved?'reviewed':'partial',d.approved?'Ready':'Check source')}</div><h3>${escape(d.name)}</h3><p class="small-copy muted">${d.pages.length} ${ext==='PPTX'?'slide':'page'}${d.pages.length===1?'':'s'}${d.lecturer?' · '+escape(d.lecturer):''}${d.year?' · '+escape(d.year):''}</p><div class="actions">${!d.approved?button('source','Check source',d.id,'small primary'):button('source','View source',d.id,'small')}</div><details class="card-options"><summary>Source options</summary><p class="small-copy muted">${escape(index)}</p>${d.approved&&d.role!=='guidance'?button('extract','Extract again',d.id,'small text'):''}</details></article>`}).join('')}</div>`:`<div class="empty"><h2>Add your learning material</h2><p>Choose current module material and a past paper. Current guidance is optional.</p>${button('guided-upload','Upload and prepare','','primary')}</div>`;
  const advanced=`<details class="advanced-section"><summary>Advanced source tools</summary><div class="actions spaced">${button('upload','Add one document')}</div><p class="small-copy muted">Files stay on this server. Pages and slides are indexed for private local search. Scanned PDFs need OCR.</p>${docs.length?`<section class="panel source-search"><form data-form="source-search"><label for="source-query">Find a concept across uploaded files</label><div class="search-box"><input id="source-query" name="query" maxlength="300" placeholder="e.g. normalization proof" required><button class="primary" type="submit">Search</button></div><div class="error" role="alert"></div></form>${search}</section>`:''}</details>`;
  return heading('Step 1 of 3','Upload your material','Choose current material and past questions once. ScopeWise assigns roles and prepares the comparison.',button('guided-upload','Upload and prepare','','primary'))+`<div class="notice neutral">Use current syllabus, slides or notes; a past paper; and optional current assessment guidance.</div>${library}${advanced}`;
}
function scopeView() {
  return heading('Advanced review','Review extracted scope','Use this only when a topic boundary or citation needs correction.',button('add-objective','＋ Add objective','','primary')) + `<div class="notice neutral">A missing topic is not automatically excluded. An exclusion needs its own source quote. If the lecturer changes, current assessment guidance must be confirmed again, while the syllabus stays separate.</div>` + (state.bundle.objectives.length ? state.bundle.objectives.map(o=>`<article class="question-card"><div class="actions">${pill(o.kind)}${pill(o.approved?'reviewed':'partial',o.approved?'Confirmed':'Draft · check it')}</div><h3 class="spaced">${escape(o.text)}</h3>${evidence(o.evidence)}<div class="actions">${button('edit-objective','Review & edit',o.id,'small')}${button('approve-objective',o.approved?'Withdraw confirmation':'Confirm objective',o.id,'small primary')}</div></article>`).join('') : `<div class="empty"><h2>What should this topic cover?</h2><p>Upload current material first, or add one objective manually with an exact source quote.</p>${button('nav','Upload material','sources','primary')}</div>`);
}
function reviewView() {
  const b=state.bundle, a=latest();
  const availability=packAvailability(),suitable=availability.available;
  const flagged=availability.notSuitable;
  const primary=a&&!a.stale&&suitable?button('quick-pack',`Make recommended pack (${suitable})`,'','primary'):button('analyze',a&&!a.stale?'Compare again':'Prepare question review','','primary');
  const cards=b.questions.map(q=>{
    const m=a?.matches.find(m=>m.question_id===q.id);
    return `<article class="question-card"><div class="actions">${pill('unknown',q.label||'Question')}${pill(q.approved?'reviewed':'partial',q.approved?'Question confirmed':'Draft question')}${m?.reviewed?pill('reviewed','Judgment confirmed'):''}</div><h3 class="spaced">${escape(q.text)}</h3><details class="source-disclosure"><summary>View original question and citation</summary>${evidence(q.evidence)}</details><div class="quiet-actions">${button('edit-question','Edit source question',q.id,'small text')}${button('approve-question',q.approved?'Withdraw question':'Confirm question',q.id,'small text')}</div>${m?`<details class="judgment-disclosure"><summary><span>Review both decisions</span><span class="actions">${pill(m.scope_status)}${pill(m.assessment_status)}</span></summary><div class="judgments"><div class="judgment"><span class="eyebrow">Does it belong in this topic?</span>${pill(m.scope_status)}<p>${escape(m.reason)}</p>${m.evidence.map(evidence).join('')}</div><div class="judgment"><span class="eyebrow">Does it match today’s answer format?</span>${pill(m.assessment_status)}<p>${escape(m.assessment_reason)}</p>${m.assessment_evidence.map(evidence).join('')}</div></div>${provenanceView(q.id)}${!a.stale?`<div class="actions">${button('edit-match','Correct evidence or decision',q.id,'small')}${button('approve-match',m.reviewed?'Reopen':'Confirm both decisions',q.id,'small primary')}</div>`:''}</details>`:''}</article>`;
  }).join('');
  const individual=b.questions.length?`<details class="advanced-section question-list"><summary>Inspect or correct individual questions (${b.questions.length})</summary><p class="small-copy muted">Open this only when a recommendation or citation needs correction.</p>${cards}</details>`:`<div class="empty"><h2>No questions prepared yet</h2><p>Upload a past paper and let ScopeWise prepare it.</p>${button('nav','Upload material','sources','primary')}</div>`;
  const more=`<details class="advanced-section"><summary>More review options</summary><div class="quiet-actions">${button('analyze','Run comparison again','','text')}${button('add-question','Add a question manually','','text')}${button('manual','Review without AI','','text')}</div>${a?`<p class="small-copy muted">${escape(a.origin)} · ${a.matches.filter(m=>m.reviewed).length} of ${a.matches.length} decisions confirmed</p>`:''}</details>`;
  return heading('Step 2 of 3','Check the prepared summary','Use the recommended set, or open individual questions only when something looks wrong.',primary)+(a?.stale?'<div class="notice">Your material changed. Prepare a new comparison before making a pack.</div>':'')+(a&&!a.stale?`<section class="panel focus-panel"><span class="eyebrow">Ready for your decision</span><h2>${suitable} unique suitable · ${flagged} need attention</h2><p>${availability.duplicates?`${availability.duplicates} exact duplicate${availability.duplicates===1?' was':'s were'} removed. `:''}Uploaded suitable questions come first. Pack generation can fill remaining slots.</p></section>`:'<div class="notice neutral">ScopeWise needs current material and at least one source question before it can prepare this summary.</div>')+individual+more;
}
function packsView() {
  const analysis=latest(),availability=packAvailability(),hasReviewed=analysis?.matches.some(m=>m.reviewed&&['aligned','partial'].includes(m.scope_status));
  const suggested=analysis?.matches.some(m=>!m.reviewed&&['aligned','partial'].includes(m.scope_status));
  const next=hasReviewed?button('pack','Build another pack ↗','','primary'):suggested?button('nav','Check recommendations first ↗','review','primary'):button('nav','Return to question review ↗','review','primary');
  const packCard=(p,number)=>`<section class="panel pack-card"><div class="panel-title"><h2>Practice pack ${number}</h2><div class="actions">${pill(p.stale?'partial':'reviewed',p.stale?'Stale':'Current')}${!p.stale?`<a class="download-link" href="/api/packs/${p.id}/export">Download / print ↗</a>`:''}</div></div><div class="notice neutral"><strong>${p.questions.length} question${p.questions.length===1?'':'s'} included</strong><div>${p.requested_limit?`You requested ${p.requested_limit}.`:'Earlier pack did not record its requested size.'}</div><div>${p.source_question_count??p.questions.length} from uploaded papers · ${p.generated_count??0} generated${p.generation_difficulty?` at ${escape(p.generation_difficulty)} difficulty`:''}</div><div>${p.available_unique_questions??availability.available} uploaded suitable · ${p.not_confirmed_suitable??availability.notSuitable} need attention · ${p.duplicates_omitted} duplicate${p.duplicates_omitted===1?'':'s'} omitted</div></div>${p.questions.map((q,n)=>`<div class="row"><span class="row-number">${n+1}</span><div class="row-main"><div class="actions">${q.generated?pill('unknown','AI-generated practice')+pill('unknown',q.difficulty):''}</div><h3>${escape(q.text)}</h3><p class="small-copy muted">${q.generated?'Grounded in: ':'Source: '}${escape(state.bundle.documents.find(d=>d.id===q.evidence.document_id)?.name||'confirmed module objective')} · page ${q.evidence.page}</p><div class="actions spaced">${pill(q.match.scope_status)}${pill(q.match.assessment_status)}</div></div></div>`).join('')}<div class="notice ${p.uncovered_objective_ids.length?'':'neutral'}"><strong>${p.uncovered_objective_ids.length?'Still needs practice':'All confirmed objectives are represented'}</strong>${p.objectives.filter(o=>p.uncovered_objective_ids.includes(o.id)).map(o=>`<div>○ ${escape(o.text)}</div>`).join('')}</div><details class="card-options"><summary>Pack details</summary><p class="footer-note">Scope v${p.scope_version} · Assessment v${p.assessment_version}<br>${escape(p.origin)}. ${escape(p.notice)}</p></details></section>`;
  if(!state.bundle.packs.length)return heading('Step 3 of 3','Your focused practice pack','Study suitable questions with source references and visible coverage gaps.',next)+`<div class="empty"><h2>Your pack is one decision away.</h2><p>Check the prepared recommendations once. ScopeWise will keep uncertain questions out and build the suitable set.</p>${button('nav','Check recommendations','review','primary')}</div>`;
  const packs=[...state.bundle.packs].reverse(),latestPack=packCard(packs[0],state.bundle.packs.length);
  const earlier=packs.length>1?`<details class="advanced-section"><summary>Earlier packs (${packs.length-1})</summary>${packs.slice(1).map((p,i)=>packCard(p,state.bundle.packs.length-i-1)).join('')}</details>`:'';
  return heading('Step 3 of 3','Your focused practice pack','Your latest pack is ready. Older packs stay out of the way unless you need them.',next)+latestPack+earlier;
}
function assistantView() {
  return heading('Grounded in your material','Ask ScopeWise','The assistant can inspect sources and prepare a pack from reviewed questions.') + `<div class="notice neutral">Uses your local Ollama model through Agent Kernel. It cannot approve evidence or predict the next exam. Sensitive documents remain on this server; Telegram messages travel through Telegram if you connect it.</div><section class="panel"><div class="chat-log" role="log" aria-live="polite">${state.chat.length?state.chat.map(m=>`<div class="chat-message ${m.role==='You'?'user':''}"><small>${escape(m.role)}</small>${escape(m.text)}</div>`).join(''):'<div class="chat-message"><small>Try a question</small>Which objectives still need practice? What evidence supports the assessment fit? Build a pack from my reviewed questions.</div>'}</div><form data-form="chat" class="chat-compose"><label class="sr-only" for="message">Ask about this module</label><textarea id="message" name="message" placeholder="What should I look at next?" maxlength="2000" required></textarea><button class="primary" type="submit">Send ↗</button><div class="error" role="alert"></div></form></section>`;
}
function openSource(id,page=1) {
  const d=state.bundle.documents.find(d=>d.id===id); if(!d)throw new Error('Source no longer available.');
  const unit=d.name.toLowerCase().endsWith('.pptx')?'slide':'page';
  showModal(d.name,`<p class="small-copy muted">Used as: ${escape(d.role)} · ${d.pages.length} ${unit}${d.pages.length===1?'':'s'} · ${d.approved?'confirmed':'waiting for your check'}</p><label for="source-page">${unit[0].toUpperCase()+unit.slice(1)}</label><select id="source-page" data-document="${id}">${d.pages.map((_,i)=>`<option value="${i+1}" ${i+1===Number(page)?'selected':''}>${unit[0].toUpperCase()+unit.slice(1)} ${i+1}</option>`).join('')}</select><pre class="source-page">${escape(d.pages[Number(page)-1]||'')}</pre><div class="modal-footer"><a class="download-link" href="/api/documents/${id}/download">Download original ↗</a>${button('approve-doc',d.approved?'Withdraw confirmation':'I checked this source',d.id,d.approved?'':'primary')}</div>`);
}
function itemForm(kind,id) {
  const item=id?state.bundle[kind+'s'].find(o=>o.id===id):null;
  const docs=state.bundle.documents.filter(d=>d.approved&&(kind==='objective'?['syllabus','notes'].includes(d.role):d.role==='paper'));
  if(!docs.length)throw new Error('Approve a suitable source document in the library first.');
  showModal(`${item?'Review':'Add'} ${kind}`,`<form data-form="item" data-kind="${kind}" data-id="${id||''}"><label for="item-text">${kind==='objective'?'Learning objective or explicit exclusion':'Full question wording'}</label><textarea id="item-text" name="text" minlength="5" maxlength="${kind==='objective'?1800:5000}" required>${escape(item?.text||'')}</textarea>${kind==='objective'?`<label for="kind">Scope</label><select id="kind" name="kind"><option value="required">Required objective</option><option value="excluded" ${item?.kind==='excluded'?'selected':''}>Explicit exclusion</option></select>`:`<label for="item-label">Question label</label><input id="item-label" name="label" maxlength="80" value="${escape(item?.label||'')}">`}<label for="document_id">Source document</label><select id="document_id" name="document_id">${docs.map(d=>`<option value="${d.id}" ${d.id===item?.evidence.document_id?'selected':''}>${escape(d.name)}</option>`).join('')}</select><label for="page">Page number</label><input id="page" name="page" type="number" min="1" max="60" value="${item?.evidence.page||1}" required><label for="quote">Exact quote from that page</label><textarea id="quote" name="quote" minlength="8" maxlength="1600" required>${escape(item?.evidence.quote||'')}</textarea><label><input name="approved" type="checkbox" ${item?.approved?'checked':''}>I checked this item against its source</label>${formFooter('Save evidence')}</form>`);
}
function matchForm(id) {
  const m=latest().matches.find(m=>m.question_id===id);
  const guidance=state.bundle.documents.filter(d=>d.role==='guidance'&&d.approved);
  const quotes=m.assessment_evidence.length?m.assessment_evidence:[{document_id:'',page:1,quote:''}];
  showModal('Review both judgments',`<p class="small-copy muted">Select only the objectives this question actually assesses. Their approved source citations will be attached automatically.</p><form data-form="match" data-id="${id}"><label for="scope-status">Syllabus fit</label><select id="scope-status" name="scope_status">${['aligned','partial','beyond_scope','uncertain'].map(s=>`<option value="${s}" ${m.scope_status===s?'selected':''}>${names[s]}</option>`).join('')}</select><label>Linked objectives and their evidence</label>${state.bundle.objectives.filter(o=>o.approved).map(o=>`<label class="check-row"><input type="checkbox" name="objective_ids" value="${o.id}" ${m.objective_ids.includes(o.id)?'checked':''}><span>${escape(o.text)}<span class="objective-quote">“${escape(o.evidence.quote)}” · page ${o.evidence.page}</span></span></label>`).join('')}<label for="reason">Why does this fit (or not fit)?</label><textarea id="reason" name="reason" maxlength="1800" required>${escape(m.reason)}</textarea><label for="assessment-status">Current assessment fit</label><select id="assessment-status" name="assessment_status">${['unknown','matches_guidance','different_format'].map(s=>`<option value="${s}" ${m.assessment_status===s?'selected':''}>${names[s]}</option>`).join('')}</select><label for="assessment-reason">What changed in the expected answer?</label><textarea id="assessment-reason" name="assessment_reason" maxlength="1200">${escape(m.assessment_reason)}</textarea>${guidance.length?quotes.map((ev,i)=>`<div class="judgment spaced"><label for="guide-${i}">Current guidance source</label><select id="guide-${i}" name="guide_${i}"><option value="">No evidence / unknown</option>${guidance.map(d=>`<option value="${d.id}" ${d.id===ev.document_id?'selected':''}>${escape(d.name)}</option>`).join('')}</select><label for="guide-page-${i}">Page</label><input id="guide-page-${i}" name="guide_page_${i}" type="number" min="1" max="60" value="${ev.page}"><label for="guide-quote-${i}">Exact supporting quote</label><textarea id="guide-quote-${i}" name="guide_quote_${i}" maxlength="1600">${escape(ev.quote)}</textarea></div>`).join(''):'<div class="notice spaced">No current guidance approved. Assessment fit will remain unknown.</div>'}<label><input type="checkbox" name="reviewed" ${m.reviewed?'checked':''}>I have reviewed both judgments and their evidence</label>${formFooter('Save judgment')}</form>`);
}
async function action(name,id,target) {
  if(name==='close')return modal.close();
  if(name==='auth-toggle'){state.register=!state.register;return render();}
  if(name==='nav'){state.page=id;return render();}
  if(name==='logout'){await post('/auth/logout');state.user=null;state.bundle=null;state.chat=[];clearTimeout(pollTimer);return render();}
  if(name==='new-course'||name==='edit-course'){
    const c=name==='edit-course'?state.bundle.course:null;
    return showModal(c?'Module settings':'Create a module',`<form data-form="course" data-id="${c?.id||''}"><label for="title">Module / focused topic</label><input id="title" name="title" maxlength="120" value="${escape(c?.title||'')}" required><label for="lecturer">Current lecturer (optional)</label><input id="lecturer" name="lecturer" maxlength="120" value="${escape(c?.lecturer||'')}"><p class="notice spaced">Changing the lecturer makes old analyses and packs stale. Current assessment guidance must be reconfirmed. We do not infer an exam change from their identity.</p>${c?button('delete-course','Delete module and all its sources',c.id,'text danger'):''}${formFooter(c?'Update module':'Create module')}</form>`);
  }
  if(name==='sample'){const c=await post('/sample');state.page='overview';await load(c.id);return toast('Synthetic sample loaded. All example judgments are human-authored.');}
  if(name==='guided-upload')return showModal('Prepare a module from your material',`<form data-form="guided-upload"><p class="muted spaced">Choose the material you already have. ScopeWise will index it locally, extract cited scope and questions, and prepare a comparison. Every result is labeled human review required.</p><label for="guided-syllabus">Current syllabus, module outline, or current notes</label><input id="guided-syllabus" name="syllabus" type="file" accept=".pdf,.pptx,.txt,.md" required><p class="footer-note">Defines what this topic includes and explicitly excludes.</p><label for="guided-paper">Past paper or practice-question file</label><input id="guided-paper" name="paper" type="file" accept=".pdf,.pptx,.txt,.md" required><p class="footer-note">Supplies the questions to compare.</p><label for="guided-guidance">Current assessment guidance (optional)</label><input id="guided-guidance" name="guidance" type="file" accept=".pdf,.pptx,.txt,.md"><p class="footer-note">Helps judge the expected answer format. Without it, assessment fit stays not established.</p><div class="notice spaced">The local model prepares drafts; it does not approve its own judgments. Review evidence before building a practice pack.</div>${formFooter('Upload and prepare my review')}</form>`);
  if(!state.bundle && name!=='telegram')throw new Error('Create a module first.');
  if(name==='delete-course'){if(!confirm('Permanently delete this module, its uploaded documents, questions and packs?'))return;await api(`/courses/${id}`,{method:'DELETE'});modal.close();return load(null);}
  if(name==='source')return openSource(id,target.dataset.page);
  if(name==='upload')return showModal('Add a source document',`<form data-form="upload"><label for="file">PDF, PowerPoint, TXT or Markdown · up to 8 MB</label><input id="file" name="file" type="file" accept=".pdf,.pptx,.txt,.md" required><label for="role">What does this file represent?</label><select id="role" name="role"><option value="syllabus">Current syllabus — defines topic boundaries</option><option value="notes">Current lecture material — adds taught detail</option><option value="paper">Past paper — supplies practice questions</option><option value="guidance">Current assessment guidance — defines answer format</option></select><div class="form-row"><div><label for="doc-lecturer">Source lecturer (optional)</label><input id="doc-lecturer" name="lecturer" maxlength="120"></div><div><label for="year">Year / term (optional)</label><input id="year" name="year" maxlength="20"></div></div><p class="footer-note">We extract text per page or slide and build a private local search index. Scanned PDFs and diagrams need OCR or descriptive text. Only upload material you may use.</p>${formFooter('Upload and index')}</form>`);
  if(name==='approve-doc'){const d=state.bundle.documents.find(d=>d.id===id);await patch(`/documents/${id}`,{approved:!d.approved});if(modal.open)modal.close();await load();return toast(d.approved?'Source confirmation withdrawn.':'Source confirmed. It can now support reviewed evidence.');}
  if(name==='extract'){await post(`/courses/${courseId()}/extract/${id}`);await load();return toast('Extraction queued. Drafts will require your review.');}
  if(name==='manual'){await post(`/courses/${courseId()}/manual-review`);await load();return toast('Manual review started. No model was called.');}
  if(name==='retry-review'){await patch(`/jobs/${id}`,{acknowledged:true});await post(`/courses/${courseId()}/analyze`);await load();return toast('Retrying automatic preparation from your uploaded files.');}
  if(name==='dismiss-job'){await patch(`/jobs/${id}`,{acknowledged:true});await load();return;}
  if(name==='analyze'){await post(`/courses/${courseId()}/analyze`);await load();return toast('Comparison queued. Both judgments will require your review.');}
  if(name.startsWith('add-')||name.startsWith('edit-objective')||name.startsWith('edit-question'))return itemForm(name.split('-')[1],id);
  if(name==='approve-objective'||name==='approve-question'){
    const kind=name.split('-')[1],item=state.bundle[kind+'s'].find(i=>i.id===id),{course_id,...payload}=item;
    await patch(`/items/${kind}/${id}`,{...payload,approved:!item.approved});return load();
  }
  if(name==='approve-match'){const m=latest().matches.find(m=>m.question_id===id);await patch(`/analyses/${latest().id}/matches`,{...m,reviewed:!m.reviewed});return load();}
  if(name==='quick-pack'){
    const {available,duplicates,notSuitable}=packAvailability();
    return showModal('Make recommended pack',`<form data-form="quick-pack"><p class="muted spaced">ScopeWise found <strong>${available} available unique question${available===1?'':'s'}</strong> suitable from your papers.</p><div class="notice neutral">${notSuitable} need attention · ${duplicates} exact duplicate${duplicates===1?'':'s'} omitted.</div><label for="quick-limit">Questions wanted</label><input id="quick-limit" name="limit" type="number" min="1" max="30" value="${Math.max(8,available)}" required><label class="check-row"><input name="generate_missing" type="checkbox" checked><span>Generate missing questions from confirmed syllabus and current guidance.</span></label><label for="quick-difficulty">Generated-question difficulty</label><select id="quick-difficulty" name="difficulty"><option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="difficult">Difficult</option></select><p class="footer-note">Uploaded questions come first. Generated questions are clearly labeled, cite their syllabus basis, and are never exam predictions.</p>${formFooter('Make pack')}</form>`);
  }
  if(name==='edit-match')return matchForm(id);
  if(name==='pack'){const {available,duplicates,notSuitable}=packAvailability();return showModal('Build a focused practice pack',`<form data-form="pack"><p class="muted spaced"><strong>${available} available unique</strong> suitable question${available===1?'':'s'}. ${notSuitable} not confirmed suitable · ${duplicates} duplicate${duplicates===1?'':'s'} omitted.</p><label for="limit">Questions wanted</label><input id="limit" name="limit" type="number" min="1" max="30" value="${Math.max(8,available)}" required><label class="check-row"><input name="generate_missing" type="checkbox" checked><span>Generate missing questions from confirmed syllabus and current guidance.</span></label><label for="difficulty">Generated-question difficulty</label><select id="difficulty" name="difficulty"><option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="difficult">Difficult</option></select><p class="footer-note">Turn this off to use uploaded questions only.</p>${formFooter('Build pack')}</form>`);}
  if(name==='telegram'){
    if(!state.status.telegram)return showModal('Telegram setup',`<p class="muted spaced">Telegram is not configured on this server yet. The owner needs to add a bot token and webhook secret, then register the HTTPS webhook using the setup script in the README.</p><p class="notice">You can already use the full review workflow and the same Agent Kernel assistant here.</p>`);
    const code=await post('/telegram/link');return showModal('Connect your private Telegram chat',`<p class="spaced">Open your bot in a <strong>private chat</strong> and send:</p><pre class="source-page">/link ${escape(code.code)}</pre><p class="notice">This single-use code expires in 10 minutes. Treat it as a temporary password. Linking replaces your previous chat connection.</p><p>Then send <code>/courses</code> and <code>/use 1</code>. Telegram can see messages sent through its platform.</p>${button('unlink-telegram','Disconnect Telegram','','danger')}`);
  }
  if(name==='unlink-telegram'){await api('/telegram/link',{method:'DELETE'});modal.close();toast('Telegram disconnected.');}
}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();target.disabled=true;
  try{await action(target.dataset.action,target.dataset.id,target);}catch(error){toast(error.message);}finally{target.disabled=false;}
});
document.addEventListener('change',async event=>{
  if(event.target.id==='course-switch'){state.chat=[];try{await load(event.target.value);}catch(error){toast(error.message);}}
  if(event.target.id==='source-page')openSource(event.target.dataset.document,event.target.value);
});
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const data=new FormData(form), fields=Object.fromEntries(data), submit=form.querySelector('[type=submit]'),errorBox=form.querySelector('.error');
  submit.disabled=true;submit.classList.add('loading');if(errorBox)errorBox.textContent='';
  try{
    switch(form.dataset.form){
      case 'auth': if(state.register)await post('/auth/register',fields);state.user=await post('/auth/login',fields);await load();break;
      case 'course': {const c=await(form.dataset.id?patch(`/courses/${form.dataset.id}`,fields):post('/courses',fields));modal.close();await load(c.id);break;}
      case 'guided-upload': {
        const uploads=[['syllabus','syllabus'],['paper','paper'],['guidance','guidance']];
        const syllabusFile=data.get('syllabus');
        if(!(syllabusFile instanceof File)||!syllabusFile.size)throw new Error('Choose a current-scope file.');
        if(!state.bundle){const title=syllabusFile.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim().slice(0,120)||'My module';const course=await post('/courses',{title,lecturer:''});await load(course.id);}
        const targetCourse=courseId(),currentLecturer=state.bundle.course.lecturer||'';
        const documentIds=[];
        for(const [field,role] of uploads){
          const file=data.get(field);if(!(file instanceof File)||!file.size)continue;
          const payload=new FormData();payload.append('file',file);payload.append('role',role);payload.append('lecturer',currentLecturer);payload.append('year','');
          const document=await api(`/courses/${targetCourse}/documents`,{method:'POST',body:payload});documentIds.push(document.id);
        }
        if(documentIds.length<2)throw new Error('Choose a current-scope file and a past paper.');
        await post(`/courses/${targetCourse}/prepare`,{document_ids:documentIds});modal.close();state.page='review';await load(targetCourse);toast('Files uploaded. The local agent is preparing your review.');break;
      }
      case 'upload': await api(`/courses/${courseId()}/documents`,{method:'POST',body:data});modal.close();state.page='sources';await load();toast('Uploaded. Inspect the text before approving it.');break;
      case 'source-search': {const result=await api(`/courses/${courseId()}/source-search?q=${encodeURIComponent(fields.query)}`);state.sourceResults=result.results;state.sourceMode=result.mode;render();break;}
      case 'item': {const kind=form.dataset.kind,payload={text:fields.text,evidence:{document_id:fields.document_id,page:Number(fields.page),quote:fields.quote},approved:data.has('approved'),[kind==='objective'?'kind':'label']:fields[kind==='objective'?'kind':'label']};await(form.dataset.id?patch(`/items/${kind}/${form.dataset.id}`,payload):post(`/courses/${courseId()}/items/${kind}`,payload));modal.close();await load();break;}
      case 'match': {const ids=data.getAll('objective_ids');const evidence=state.bundle.objectives.filter(o=>ids.includes(o.id)).map(o=>o.evidence);const assessment_evidence=Object.keys(fields).filter(k=>/^guide_\d+$/.test(k)&&fields[k]).map(k=>({document_id:fields[k],page:Number(fields['guide_page_'+k.split('_')[1]]),quote:fields['guide_quote_'+k.split('_')[1]]}));const payload={question_id:form.dataset.id,scope_status:fields.scope_status,objective_ids:ids,reason:fields.reason,evidence,assessment_status:fields.assessment_status,assessment_reason:fields.assessment_reason,assessment_evidence,reviewed:data.has('reviewed')};await patch(`/analyses/${latest().id}/matches`,payload);modal.close();await load();break;}
      case 'quick-pack': await patch(`/analyses/${latest().id}/matches/review-suitable`,{confirmed:true});if(data.has('generate_missing'))await post(`/courses/${courseId()}/packs/generate`,{limit:Number(fields.limit),difficulty:fields.difficulty});else await post(`/courses/${courseId()}/packs`,{limit:Number(fields.limit)});modal.close();state.page='packs';await load();toast(data.has('generate_missing')?'Generating missing questions locally…':'Practice pack created.');break;
      case 'pack': if(data.has('generate_missing'))await post(`/courses/${courseId()}/packs/generate`,{limit:Number(fields.limit),difficulty:fields.difficulty});else await post(`/courses/${courseId()}/packs`,{limit:Number(fields.limit)});modal.close();state.page='packs';await load();toast(data.has('generate_missing')?'Generating missing questions locally…':'Practice pack created. Check the coverage gaps too.');break;
      case 'chat': {const id=courseId();state.chat.push({role:'You',text:fields.message});toast('Asking the local assistant…');const result=await post(`/courses/${id}/chat`,{message:fields.message});if(courseId()===id){state.chat.push({role:'ScopeWise',text:result.reply});await load();}break;}
    }
  }catch(error){if(errorBox&&form.isConnected)errorBox.textContent=error instanceof SyntaxError?'Evidence must be valid JSON. Keep the array and quote characters.':error.message;else toast(error.message);}
  finally{submit.disabled=false;submit.classList.remove('loading');}
});
(async()=>{try{state.status=await api('/status');try{state.user=await api('/me');}catch{}if(state.user)await load();else render();}catch(error){root.innerHTML=`<main id="main" class="empty"><h1>Workspace unavailable</h1><p>${escape(error.message)}</p><p>Check the server and reload this page.</p></main>`;}})();
